def load():
    raw = PAYLOAD if isinstance(PAYLOAD, dict) else json.loads(PAYLOAD)
    pairs = [(base64.b64decode(a).decode("utf-8"), base64.b64decode(b).decode("utf-8")) for a, b in raw["pairs"]]
    ups = {k: base64.b64decode(v) for k, v in raw["ups"].items()}
    docs = {k: base64.b64decode(v) for k, v in raw["docs"].items()}
    return pairs, ups, docs

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def syntax(data: bytes, name: str):
    try:
        compile(data, name, "exec")
    except SyntaxError as exc:
        return "Zeile %s: %s" % (exc.lineno, exc.msg)
    return None

def lage_stand(data: bytes, pairs):
    alt = neu = 0
    for a, b in pairs:
        ca, cb = data.count(a.encode()), data.count(b.encode())
        if ca > 1 or cb > 1 or (ca and cb):
            return "halt", "USV-Stelle mehrfach oder gemischt"
        alt += ca
        neu += cb
    if alt == len(pairs) and neu == 0:
        return "alt", "vier USV-Stellen alt"
    if neu == len(pairs) and alt == 0:
        return "neu", "vier USV-Stellen neu"
    return "halt", "unbekannte USV-Stellen alt %d neu %d von %d" % (alt, neu, len(pairs))

def tausch(data: bytes, pairs, rueck: bool) -> bytes:
    out = data
    seq = [(b, a) for a, b in pairs] if rueck else pairs
    for a, b in seq:
        raw_a, raw_b = a.encode(), b.encode()
        if out.count(raw_a) != 1:
            raise RuntimeError("USV-Stelle nicht genau einmal")
        out = out.replace(raw_a, raw_b, 1)
    return out

def rest(data: bytes, pairs, neu: bool) -> bytes:
    out = data
    parts = [b.encode() if neu else a.encode() for a, b in pairs]
    for part in parts:
        if out.count(part) != 1:
            raise RuntimeError("Restpruefung: Stelle fehlt")
        out = out.replace(part, b"", 1)
    return out

def fenster(now=None):
    try:
        from zoneinfo import ZoneInfo
        jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    except Exception as exc:
        return False, "Zeitzone Europe/Berlin nicht verfuegbar (%s)" % exc
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin %s Minute %02d" % (jetzt.strftime("%Y-%m-%d %H:%M"), m)

def guard(text: str):
    err = []
    if 'EG_LEARN_NAME = "usv_eg_learn.json"' not in text:
        err.append("Lernbasis fehlt")
    if 'EG_AKKU_EINBAU = "2026-05"' not in text or 'AKKU_EINBAU = "2026-05"' not in text:
        err.append("Einbau ist nicht 05.2026")
    if 'if not p.get("test_seen"):' not in text or "done and passed" not in text:
        err.append("Test zaehlt ohne abgeschlossenes ups.test.result")
    if "Akkubetrieb und eine kuerzere Laufzeit sind kein Test" not in text:
        err.append("Akkubetrieb koennte als Test zaehlen")
    if "r = dict(EG_SOH)" not in text:
        err.append("Start-SoH ist nicht leer")
    if 'sendall(("INSTCMD' in text or "Abschaltung bei 20 %" in text.split("def selftest", 1)[0]:
        err.append("Steuerung oder Abschaltung")
    learn = text.split("class EgLearn", 1)[-1].split("class EgPoller", 1)[0]
    if "STATE_NAME" in learn:
        err.append("EG schreibt die Spitzboden-Datei")
    return err

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-usvegsoh")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        if tmp.read_bytes() != data:
            raise RuntimeError("temporaere Datei weicht ab")
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-usvegsoh-*"))
    bak = path.with_name(path.name + ".bak-usvegsoh-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for restlich in alt[:-2]:
        try:
            restlich.unlink()
        except OSError:
            pass
    return bak

def keep_ok(name: str, digest: str) -> bool:
    if name == "dashboard.py":
        return digest == KEEP["dashboard.py"] or digest.startswith(DASH_DSL)
    return digest == KEEP[name]

def fingerprints(ordner: Path):
    return {name: sha((ordner/name).read_bytes()) if (ordner/name).is_file() else None for name in UNBERUEHRT}

def apply_dir(ordner: Path, dry: bool, kein: bool, pairs, ups, docs) -> int:
    pfade = {n: ordner/n for n in ("ups_manager.py", "prepper_docs.py", "lage_pages.py")}
    for pfad in pfade.values():
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % pfad.name)
            return 2
    dash_before = None
    for name in KEEP:
        pfad = ordner/name
        if not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        roh = pfad.read_bytes()
        if name == "dashboard.py":
            dash_before = roh
        if not keep_ok(name, sha(roh)):
            print("STOP: %s %s ist nicht die installierte Stufe 1" % (name, sha(roh)[:16]))
            return 2
    u, d, l = pfade["ups_manager.py"].read_bytes(), pfade["prepper_docs.py"].read_bytes(), pfade["lage_pages.py"].read_bytes()
    us, ds = sha(u), sha(d)
    ls, lm = lage_stand(l, pairs)
    if ls == "halt":
        print("STOP: lage_pages.py " + lm)
        return 2
    if us not in (ups["alt"], ups["neu_sha"]) or ds not in (docs["alt"], docs["neu_sha"]):
        print("STOP: ups %s docs %s ist nicht die Kacheln-Basis" % (us[:16], ds[:16]))
        return 2
    if (us == ups["alt"]) != (ds == docs["alt"]) or (us == ups["neu_sha"]) != (ls == "neu"):
        print("STOP: Mischstand")
        return 2
    if us == ups["neu_sha"] and ls == "neu":
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    if guard(ups["body"].decode()):
        print("STOP: Guard " + "; ".join(guard(ups["body"].decode())))
        return 2
    try:
        l2 = tausch(l, pairs, False)
    except RuntimeError as exc:
        print("STOP: %s" % exc)
        return 2
    if rest(l, pairs, False) != rest(l2, pairs, True) or lage_stand(l2, pairs)[0] != "neu":
        print("STOP: lage_pages.py wuerde ausserhalb der USV-Stellen geaendert")
        return 2
    if syntax(l, "lage_pages.py") or syntax(l2, "lage_pages.py") or syntax(ups["body"], "ups_manager.py"):
        print("STOP: Syntax")
        return 2
    frei, meldung = fenster()
    print(meldung)
    if not frei and not dry:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    vorher = fingerprints(ordner)
    try:
        sichern(pfade["ups_manager.py"], u)
        sichern(pfade["prepper_docs.py"], d)
        sichern(pfade["lage_pages.py"], l)
        schreiben(pfade["ups_manager.py"], ups["body"])
        schreiben(pfade["prepper_docs.py"], docs["body"])
        schreiben(pfade["lage_pages.py"], l2)
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    if fingerprints(ordner) != vorher or sha(pfade["ups_manager.py"].read_bytes()) != ups["neu_sha"]:
        print("STOP: Config, Lernstand oder Hash nach dem Schreiben falsch")
        return 3
    if (ordner/"dashboard.py").read_bytes() != dash_before:
        print("STOP: dashboard.py wurde veraendert")
        return 3
    print("geschrieben. Fremde Lage-Bytes, usv_eg.json und Spitzboden-Zustand unveraendert.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Dateien sind neu, der Neustart bleibt in der Sperre aus.")
        return 2
    subprocess.run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet. Tunnel und prepper-sdr nicht.")
    print("Ob die EG-Verbindung steht, prueft dieses Skript nicht.")
    return 0

def selftest() -> int:
    import io, tempfile
    from contextlib import redirect_stdout
    pairs, ups_map, docs_map = load()
    ups = {"alt": sha(ups_map["old"]), "neu": sha(ups_map["new"]), "neu_sha": sha(ups_map["new"]), "bytes": ups_map["new"]}
    # fix keys below in apply; selftest uses local dict
    text = ups_map["new"].decode()
    assert guard(text) == [], guard(text)
    assert guard(text.replace('if not p.get("test_seen"):', "if False:", 1))
    assert guard(text.replace("r = dict(EG_SOH)", "r = {'pct': 100}", 1))
    lage = "".join(a for a, _b in pairs).encode() + b"\n# FREMD-DSL-GAS\nwert = 1\n"
    assert lage_stand(lage, pairs)[0] == "alt"
    neu = tausch(lage, pairs, False)
    assert rest(lage, pairs, False) == rest(neu, pairs, True)
    assert b"FREMD-DSL-GAS" in neu and lage_stand(neu, pairs)[0] == "neu"
    assert lage_stand(b"unbekannt\n", pairs)[0] == "halt"
    assert keep_ok("dashboard.py", KEEP["dashboard.py"])
    assert keep_ok("dashboard.py", DASH_DSL + "ab" * 24)
    assert not keep_ok("dashboard.py", "aaaaaaaaaaaaaaaa" + "00" * 24)
    assert not keep_ok("prepper_sdr.py", DASH_DSL + "ab" * 24)
    assert fenster(datetime(2026, 11, 7, 12, 10))[0]
    assert not fenster(datetime(2026, 11, 7, 23, 50))[0]
    assert not fenster(datetime(2026, 11, 7, 0, 2))[0]
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    pairs, ups_map, docs_map = load()
    ups_use = {"alt": sha(ups_map["old"]), "neu_sha": sha(ups_map["new"]), "body": ups_map["new"]}
    docs_use = {"alt": sha(docs_map["old"]), "neu_sha": sha(docs_map["new"]), "body": docs_map["new"]}
    return apply_dir(wurzel, dry, kein, pairs, ups_use, docs_use)

